//! The App Store catalog index (`catalog.json`, generated by `hinteros-catalog`'s
//! `lib.mkIndex`, schema `hinteros-catalog/schema/index.schema.json`, index version 4).
//!
//! The running generation installs it at `/run/current-system/sw/share/hinteros/catalog.json`
//! (with the vendor terms next to it under `terms/`). Both daemons read it: the system service
//! checks `apps.install`/`apps.remove` ids against it, the session daemon serves it to the
//! launcher as `store.list`. Receivers ignore unknown fields; another `indexVersion` is
//! refused, like an API major.
//!
//! The index is trusted data (it comes from the signed system revision), but it is still parsed
//! strictly where it reaches root: ids and data paths are checked again here.

use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};

/// The index version this code reads.
pub const INDEX_VERSION: u32 = 4;

/// Box features an app may need (the index's `boxFeatures`, apps.md "Box requirements").
pub const BOX_FEATURES: &[&str] = &["graphics32", "steam-devices"];

pub fn is_box_feature(s: &str) -> bool {
    BOX_FEATURES.contains(&s)
}

/// Sandbox permissions an app may declare (`permissions`, optional), in the order
/// they are shown. Other names are ignored (not enforced, so not listed).
pub const PERMISSIONS: &[&str] = &["gamepad", "mic", "downloads", "lan"];

/// Whether an app needs a permission (`permissions` values).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Need {
    Required,
    Optional,
    /// A value this code does not know: treated like `required` (it cannot be switched off).
    #[serde(other)]
    Unknown,
}

impl Need {
    pub fn required(self) -> bool {
        self != Need::Optional
    }
}

/// What an entry is: an app (per profile, in the Store) or a box-wide service.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum EntryKind {
    #[default]
    App,
    Service,
    /// A kind this code does not know: ignored like a service (never installable as an app).
    #[serde(other)]
    Unknown,
}

/// Default location of the running generation's index.
pub const DEFAULT_INDEX: &str = "/run/current-system/sw/share/hinteros/catalog.json";

/// Most apps one `apps.install` / `apps.remove` may name.
pub const MAX_IDS: usize = 8;

/// `^[a-z0-9][a-z0-9-]{0,31}$` (catalog ids, also what `state.json`'s `apps` stores).
pub fn is_app_id(s: &str) -> bool {
    let b = s.as_bytes();
    !b.is_empty()
        && b.len() <= 32
        && (b[0].is_ascii_lowercase() || b[0].is_ascii_digit())
        && b.iter()
            .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || *c == b'-')
}

/// A terms version: `^[A-Za-z0-9._-]{1,32}$`.
pub fn is_terms_version(s: &str) -> bool {
    (1..=32).contains(&s.len())
        && s.bytes()
            .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'.' | b'_' | b'-'))
}

/// A `dataPaths` entry: relative to a home, 1 to 200 bytes, no leading `/` or `~`, no empty,
/// `.` or `..` components, no wildcards, no control characters.
pub fn is_data_path(s: &str) -> bool {
    !s.is_empty()
        && s.len() <= 200
        && !s.starts_with('/')
        && !s.starts_with('~')
        && !s.ends_with('/')
        && !s
            .chars()
            .any(|c| c.is_control() || matches!(c, '*' | '?' | '[' | ']' | '\\'))
        && s.split('/').all(|c| !c.is_empty() && c != "." && c != "..")
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Status {
    Available,
    Retired,
    Removed,
    /// A status this code does not know: treated like `retired` (keeps working, not
    /// installable). Also the status of an available entry that needs a box feature this code
    /// does not know.
    #[serde(other)]
    Unknown,
}

#[derive(Debug, Clone, Default, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Icon {
    pub desktop_id: Option<String>,
    pub site_url: Option<String>,
    pub icon_url: Option<String>,
    /// Hex SHA-256 of the `icon_url` file, required with it: the session daemon
    /// keeps a download only if it matches.
    pub sha256: Option<String>,
    #[serde(default)]
    pub firefox_profile: bool,
}

#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
pub struct Terms {
    pub title: String,
    pub version: String,
    pub url: String,
    pub retrieved: String,
    /// `terms/<name>.txt`, relative to the index file.
    pub file: String,
}

/// The upstream README (index field `readme`), shown on the Store page.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
pub struct Readme {
    pub url: String,
    pub retrieved: String,
    /// `readme/<name>.md`, relative to the index file.
    pub file: String,
}

/// How an app reaches the box (the index's `delivery`).
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Delivery {
    /// From the binary cache.
    #[default]
    Download,
    /// Fetched from the vendor and built on the box during install. A value this code does not
    /// know is treated the same way: the slower case, and the one that needs internet.
    #[serde(other)]
    Build,
}

/// One entry. Tombstones (`status: removed`) only have `id`, `kind`, `name`, `status` and
/// `statusReason`; everything else then has its default.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Entry {
    pub id: String,
    pub name: String,
    #[serde(default)]
    pub summary: String,
    #[serde(default)]
    pub description: String,
    #[serde(default)]
    pub category: String,
    #[serde(default)]
    pub homepage: String,
    #[serde(default)]
    pub kind: EntryKind,
    /// Box features the app needs.
    #[serde(default)]
    pub box_features: Vec<String>,
    /// Installer app step: `offered`, `ticked` or none.
    #[serde(default)]
    pub starter: Option<String>,
    /// Services the app needs.
    #[serde(default)]
    pub needs_services: Vec<String>,
    #[serde(default, rename = "sizeMiB")]
    pub size_mib: u64,
    #[serde(default)]
    pub icon: Icon,
    #[serde(default)]
    pub depends: Vec<String>,
    #[serde(default)]
    pub conflicts: Vec<String>,
    #[serde(default)]
    pub on_iso: bool,
    #[serde(default)]
    pub data_paths: Vec<String>,
    #[serde(default)]
    pub terms: Option<Terms>,
    #[serde(default)]
    pub readme: Option<Readme>,
    pub status: Status,
    #[serde(default)]
    pub status_reason: Option<String>,
    /// Missing: unfree, so an entry that does not say is never offered without terms.
    #[serde(default = "yes")]
    pub unfree: bool,
    #[serde(default)]
    pub delivery: Delivery,
    /// Sandbox permissions (name -> need; optional).
    #[serde(default)]
    pub permissions: BTreeMap<String, Need>,
    /// `false`: the app runs without the sandbox (optional; default true).
    #[serde(default = "yes")]
    pub sandbox: bool,
    /// Services: ports the system opens while the service is on (optional).
    #[serde(default)]
    pub ports: Vec<Port>,
    /// Services: the setup flow the Server section shows (`jellyfin-server`,
    /// `plex-media-server`, `tailscale`, `cloudflare-tunnel`), as written; see
    /// [`Entry::setup_kind`]. Optional.
    #[serde(default)]
    pub setup: Option<String>,
    /// Services: directories below `/var/lib` that `services.disable {delete_data}`
    /// removes (checked with [`is_state_dir`]). Optional.
    #[serde(default)]
    pub state_dirs: Vec<String>,
}

/// The setup flows the Server section knows (catalog `setup`, the service's id).
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum Setup {
    JellyfinServer,
    PlexMediaServer,
    Tailscale,
    CloudflareTunnel,
}

impl Setup {
    pub const ALL: &[Setup] = &[
        Setup::JellyfinServer,
        Setup::PlexMediaServer,
        Setup::Tailscale,
        Setup::CloudflareTunnel,
    ];

    pub fn from_name(s: &str) -> Option<Self> {
        match s {
            "jellyfin-server" => Some(Setup::JellyfinServer),
            "plex-media-server" => Some(Setup::PlexMediaServer),
            "tailscale" => Some(Setup::Tailscale),
            "cloudflare-tunnel" => Some(Setup::CloudflareTunnel),
            _ => None,
        }
    }
}

/// A port a service opens (catalog `ports`).
#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
pub struct Port {
    pub port: u16,
    pub proto: Proto,
    pub from: PortFrom,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Proto {
    Tcp,
    Udp,
    #[serde(other)]
    Unknown,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum PortFrom {
    Lan,
    Any,
    #[serde(other)]
    Unknown,
}

impl Entry {
    /// The setup flow (`None`: no setup, or a value this code does not know: on/off only).
    pub fn setup_kind(&self) -> Option<Setup> {
        self.setup.as_deref().and_then(Setup::from_name)
    }

    /// The first TCP port (the address a service is used at).
    pub fn tcp_port(&self) -> Option<u16> {
        self.ports
            .iter()
            .find(|p| p.proto == Proto::Tcp)
            .map(|p| p.port)
    }
}

/// A `stateDirs` entry: relative to `/var/lib`, `^[A-Za-z0-9._-]+(/[A-Za-z0-9._-]+)*$`, no `.` or
/// `..` component, at most 200 bytes.
pub fn is_state_dir(s: &str) -> bool {
    !s.is_empty()
        && s.len() <= 200
        && s.split('/').all(|c| {
            !c.is_empty()
                && c != "."
                && c != ".."
                && c.bytes()
                    .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'.' | b'_' | b'-'))
        })
}

fn yes() -> bool {
    true
}

#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "camelCase")]
struct RawIndex {
    index_version: u32,
    entries: Vec<Entry>,
}

/// A parsed, checked index.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Index {
    /// The directory of the index file (terms files are relative to it).
    pub dir: PathBuf,
    /// `indexVersion` of the file.
    pub version: u32,
    pub entries: BTreeMap<String, Entry>,
}

#[derive(Debug, thiserror::Error)]
pub enum IndexError {
    #[error("{0} not found")]
    Missing(PathBuf),
    #[error("reading {0}: {1}")]
    Io(PathBuf, std::io::Error),
    #[error("{0} is invalid: {1}")]
    Invalid(PathBuf, String),
    #[error("{path} has index version {found}, this daemon reads version {INDEX_VERSION}")]
    Version { path: PathBuf, found: u32 },
}

impl Index {
    pub fn load(path: &Path) -> Result<Self, IndexError> {
        let bytes = match std::fs::read(path) {
            Ok(b) => b,
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
                return Err(IndexError::Missing(path.to_owned()));
            }
            Err(e) => return Err(IndexError::Io(path.to_owned(), e)),
        };
        let dir = path.parent().unwrap_or(Path::new("/")).to_owned();
        Self::parse(&bytes, dir).map_err(|e| match e {
            ParseError::Version(found) => IndexError::Version {
                path: path.to_owned(),
                found,
            },
            ParseError::Invalid(m) => IndexError::Invalid(path.to_owned(), m),
        })
    }

    pub fn parse(bytes: &[u8], dir: PathBuf) -> Result<Self, ParseError> {
        // The version first, so a future format is reported as such and not as garbage.
        #[derive(Deserialize)]
        #[serde(rename_all = "camelCase")]
        struct Version {
            index_version: u32,
        }
        let v: Version =
            serde_json::from_slice(bytes).map_err(|e| ParseError::Invalid(e.to_string()))?;
        if v.index_version != INDEX_VERSION {
            return Err(ParseError::Version(v.index_version));
        }
        let raw: RawIndex =
            serde_json::from_slice(bytes).map_err(|e| ParseError::Invalid(e.to_string()))?;
        let mut entries = BTreeMap::new();
        for mut e in raw.entries {
            check_entry(&e).map_err(ParseError::Invalid)?;
            // A box feature this code does not know (a newer catalog): the entry is not
            // installable, like an unknown status (an installed app keeps working), and the
            // feature asks nothing of this system. The rest of the index stays usable.
            if !e.box_features.iter().all(|f| is_box_feature(f)) {
                e.box_features.retain(|f| is_box_feature(f));
                if e.status == Status::Available {
                    e.status = Status::Unknown;
                }
            }
            if entries.insert(e.id.clone(), e).is_some() {
                return Err(ParseError::Invalid("duplicate id".into()));
            }
        }
        Ok(Self {
            dir,
            version: raw.index_version,
            entries,
        })
    }

    pub fn get(&self, id: &str) -> Option<&Entry> {
        self.entries.get(id)
    }

    /// An app entry that is not a tombstone (not a service either).
    pub fn app(&self, id: &str) -> Option<&Entry> {
        self.get(id)
            .filter(|e| e.kind == EntryKind::App && e.status != Status::Removed)
    }

    /// The box features `ids` need (sorted, unique; unknown ids and services count nothing).
    pub fn box_features<'a>(&self, ids: impl IntoIterator<Item = &'a String>) -> Vec<String> {
        let set: BTreeSet<String> = ids
            .into_iter()
            .filter_map(|id| self.app(id))
            .flat_map(|e| e.box_features.iter().cloned())
            .collect();
        set.into_iter().collect()
    }

    /// The absolute path of an entry's terms text (checked to stay in `terms/`).
    pub fn terms_file(&self, terms: &Terms) -> PathBuf {
        self.dir.join(&terms.file)
    }

    /// The absolute path of an entry's README (checked to stay in `readme/`).
    pub fn readme_file(&self, readme: &Readme) -> PathBuf {
        self.dir.join(&readme.file)
    }

    /// Every app `ids` needs, `ids` first, then their dependencies (transitively), each once.
    /// `Err(id)`: an id (or a dependency) that is not in the index.
    pub fn with_dependencies(&self, ids: &[String]) -> Result<Vec<String>, String> {
        let mut out: Vec<String> = Vec::new();
        let mut seen = BTreeSet::new();
        let mut queue: std::collections::VecDeque<String> = ids.iter().cloned().collect();
        while let Some(id) = queue.pop_front() {
            if !seen.insert(id.clone()) {
                continue;
            }
            let entry = self.get(&id).ok_or_else(|| id.clone())?;
            out.push(id);
            queue.extend(entry.depends.iter().cloned());
        }
        Ok(out)
    }
}

#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum ParseError {
    #[error("unsupported index version {0}")]
    Version(u32),
    #[error("{0}")]
    Invalid(String),
}

/// `<dir><name><ext>` with a plain file name (no `/`, no leading `.`).
fn is_file_in(file: &str, dir: &str, ext: &str) -> bool {
    file.strip_prefix(dir).is_some_and(|n| {
        n.ends_with(ext)
            && n.len() > ext.len()
            && n.bytes()
                .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'.' | b'_' | b'-'))
            && !n.starts_with('.')
    })
}

fn check_entry(e: &Entry) -> Result<(), String> {
    if !is_app_id(&e.id) {
        return Err(format!("bad id {:?}", e.id));
    }
    if e.icon.icon_url.is_some() && e.icon.sha256.is_none() {
        return Err(format!("{}: iconUrl needs sha256", e.id));
    }
    for d in e
        .depends
        .iter()
        .chain(&e.conflicts)
        .chain(&e.needs_services)
    {
        if !is_app_id(d) {
            return Err(format!("{}: bad id {d:?} in depends/conflicts", e.id));
        }
    }
    for p in &e.data_paths {
        if !is_data_path(p) {
            return Err(format!("{}: bad data path {p:?}", e.id));
        }
    }
    for d in &e.state_dirs {
        if !is_state_dir(d) {
            return Err(format!("{}: bad state dir {d:?}", e.id));
        }
    }
    if let Some(t) = &e.terms
        && (!is_file_in(&t.file, "terms/", ".txt") || !is_terms_version(&t.version))
    {
        return Err(format!("{}: bad terms", e.id));
    }
    if let Some(r) = &e.readme
        && !is_file_in(&r.file, "readme/", ".md")
    {
        return Err(format!("{}: bad readme", e.id));
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    pub const SAMPLE: &str = r#"{
      "indexVersion": 4,
      "entries": [
        { "id": "steam", "kind": "app", "name": "Steam", "summary": "s", "description": "d",
          "category": "games", "homepage": "https://store.steampowered.com", "sizeMiB": 1000,
          "icon": { "desktopId": "steam", "siteUrl": "https://store.steampowered.com" },
          "boxFeatures": ["graphics32", "steam-devices"], "depends": [], "conflicts": [],
          "starter": "offered", "onIso": false, "needsServices": [],
          "dataPaths": [".local/share/Steam", ".steam"],
          "terms": { "title": "Steam Subscriber Agreement", "version": "2026-09-10",
                     "url": "https://store.steampowered.com/subscriber_agreement/",
                     "retrieved": "2026-10-06", "file": "terms/steam-2026-09-10.txt" },
          "readme": { "url": "https://github.com/x/y/blob/0/README.md", "retrieved": "2026-10-25",
                      "file": "readme/steam.md" },
          "status": "available", "statusReason": null, "unfree": true, "delivery": "download",
          "futureField": 1 },
        { "id": "plex-htpc", "kind": "app", "name": "Plex", "status": "available",
          "unfree": true, "delivery": "build" },
        { "id": "youtube", "kind": "app", "name": "YouTube", "status": "available",
          "starter": "ticked", "unfree": false, "delivery": "download",
          "icon": { "iconUrl": "https://x.test/i.png", "sha256": "ab12" } },
        { "id": "jellyfin-server", "kind": "service", "name": "Jellyfin server",
          "status": "available", "boxFeatures": [], "unfree": false, "delivery": "download" },
        { "id": "old-app", "kind": "app", "name": "Old app", "status": "removed",
          "statusReason": "gone" }
      ]
    }"#;

    #[test]
    fn parses_the_index() {
        let i = Index::parse(SAMPLE.as_bytes(), "/idx".into()).unwrap();
        assert_eq!(i.version, 4);
        let s = i.get("steam").unwrap();
        assert_eq!(s.size_mib, 1000);
        assert_eq!(s.icon.desktop_id.as_deref(), Some("steam"));
        assert_eq!(s.data_paths, [".local/share/Steam", ".steam"]);
        assert_eq!(s.kind, EntryKind::App);
        assert_eq!(s.box_features, ["graphics32", "steam-devices"]);
        assert_eq!(s.starter.as_deref(), Some("offered"));
        assert_eq!(
            i.terms_file(s.terms.as_ref().unwrap()),
            Path::new("/idx/terms/steam-2026-09-10.txt")
        );
        assert_eq!(
            i.readme_file(s.readme.as_ref().unwrap()),
            Path::new("/idx/readme/steam.md")
        );
        assert!(i.get("old-app").unwrap().readme.is_none());
        assert_eq!(i.get("old-app").unwrap().status, Status::Removed);
        assert!(i.get("old-app").unwrap().data_paths.is_empty());
        assert_eq!(
            i.get("youtube").unwrap().icon.sha256.as_deref(),
            Some("ab12")
        );
        assert_eq!(i.get("jellyfin-server").unwrap().kind, EntryKind::Service);
        assert!(i.app("jellyfin-server").is_none() && i.app("old-app").is_none());
        let ids: Vec<String> = ["youtube", "steam", "jellyfin-server", "nope"]
            .iter()
            .map(|s| s.to_string())
            .collect();
        assert_eq!(i.box_features(&ids), ["graphics32", "steam-devices"]);
        // Permissions and sandbox are optional.
        assert!(s.permissions.is_empty() && s.sandbox);
        let p = Index::parse(
            br#"{"indexVersion":4,"entries":[
              {"id":"a","kind":"app","name":"A","status":"available",
               "permissions":{"gamepad":"required","mic":"optional","x":"later"},"sandbox":false}]}"#,
            "/".into(),
        )
        .unwrap();
        let a = p.get("a").unwrap();
        assert!(!a.sandbox);
        assert_eq!(a.permissions["gamepad"], Need::Required);
        assert_eq!(a.permissions["mic"], Need::Optional);
        assert!(a.permissions["x"].required());
        assert!(!Need::Optional.required());
    }

    #[test]
    fn unfree_and_delivery() {
        let i = Index::parse(SAMPLE.as_bytes(), "/".into()).unwrap();
        let view = |id: &str| {
            let e = i.get(id).unwrap();
            (e.unfree, e.delivery)
        };
        assert_eq!(view("steam"), (true, Delivery::Download));
        assert_eq!(view("plex-htpc"), (true, Delivery::Build));
        assert_eq!(view("youtube"), (false, Delivery::Download));
        // An entry that does not say is unfree (never offered without terms); a delivery this
        // code does not know is a build.
        let i = Index::parse(
            br#"{"indexVersion":4,"entries":[
              {"id":"a","kind":"app","name":"A","status":"available"},
              {"id":"b","kind":"app","name":"B","status":"available","delivery":"later"}]}"#,
            "/".into(),
        )
        .unwrap();
        assert!(i.get("a").unwrap().unfree);
        assert_eq!(i.get("b").unwrap().delivery, Delivery::Build);
    }

    #[test]
    fn unknown_fields_load_and_other_versions_do_not() {
        let i = Index::parse(
            br#"{"indexVersion":4,"later":1,"entries":[
              {"id":"a","kind":"app","name":"A","status":"available","later":{"x":[1]}}]}"#,
            "/".into(),
        )
        .unwrap();
        assert!(i.app("a").is_some());
        for v in [2, 3, 5] {
            assert_eq!(
                Index::parse(
                    format!(r#"{{"indexVersion":{v},"entries":[]}}"#).as_bytes(),
                    "/".into()
                )
                .unwrap_err(),
                ParseError::Version(v)
            );
        }
        // The version comes first: a newer index whose shape this code cannot read is still
        // reported as a version, not as garbage.
        assert_eq!(
            Index::parse(br#"{"indexVersion":5,"entries":"later"}"#, "/".into()).unwrap_err(),
            ParseError::Version(5)
        );
        let e = IndexError::Version {
            path: "catalog.json".into(),
            found: 5,
        };
        assert_eq!(
            e.to_string(),
            "catalog.json has index version 5, this daemon reads version 4"
        );
        assert!(
            e.to_string().ends_with("this daemon reads version 4"),
            "{e}"
        );
    }

    #[test]
    fn refuses_bad_entries() {
        for bad in [
            r#"{"indexVersion":4,"entries":[{"id":"../x","name":"x","status":"available"}]}"#,
            r#"{"indexVersion":4,"entries":[{"id":"a","name":"x","status":"available","dataPaths":["../../etc"]}]}"#,
            r#"{"indexVersion":4,"entries":[{"id":"a","name":"x","status":"available","dataPaths":["/etc"]}]}"#,
            r#"{"indexVersion":4,"entries":[{"id":"a","name":"x","status":"available","depends":["A"]}]}"#,
            r#"{"indexVersion":4,"entries":[{"id":"a","name":"x","status":"available","terms":{"title":"t","version":"1","url":"u","retrieved":"r","file":"../x.txt"}}]}"#,
            r#"{"indexVersion":4,"entries":[{"id":"a","name":"x","status":"available","readme":{"url":"u","retrieved":"r","file":"readme/../x.md"}}]}"#,
            r#"{"indexVersion":4,"entries":[{"id":"a","name":"x","status":"available","readme":{"url":"u","retrieved":"r","file":"terms/a.md"}}]}"#,
            r#"{"indexVersion":4,"entries":[{"id":"a","name":"x","status":"available","icon":{"iconUrl":"https://x.test/i.png"}}]}"#,
            r#"{"indexVersion":4,"entries":[{"id":"a","name":"x","status":"available"},{"id":"a","name":"y","status":"available"}]}"#,
            r#"{"indexVersion":4,"apps":[]}"#,
            r#"{"entries":[]}"#,
        ] {
            assert!(
                Index::parse(bad.as_bytes(), "/".into()).is_err(),
                "accepted {bad}"
            );
        }
        let i = Index::parse(
            br#"{"indexVersion":4,"entries":[{"id":"a","name":"x","status":"later"},{"id":"b","kind":"later","name":"y","status":"available"}]}"#,
            "/".into(),
        )
        .unwrap();
        assert_eq!(i.get("a").unwrap().status, Status::Unknown);
        assert_eq!(i.get("b").unwrap().kind, EntryKind::Unknown);
        assert!(i.app("b").is_none());
    }

    #[test]
    fn an_unknown_box_feature_makes_only_its_entry_not_installable() {
        let i = Index::parse(
            br#"{"indexVersion":4,"entries":[
              {"id":"a","kind":"app","name":"x","status":"available","boxFeatures":["graphics32","hidraw"]},
              {"id":"b","kind":"app","name":"y","status":"removed","boxFeatures":["hidraw"]},
              {"id":"c","kind":"app","name":"z","status":"available","boxFeatures":["graphics32"]}]}"#,
            "/".into(),
        )
        .unwrap();
        let a = i.get("a").unwrap();
        assert_eq!(a.status, Status::Unknown);
        assert_eq!(a.box_features, ["graphics32"]);
        assert_eq!(i.get("b").unwrap().status, Status::Removed);
        assert_eq!(i.get("c").unwrap().status, Status::Available);
        let ids = ["a".to_string(), "c".to_string()];
        assert_eq!(i.box_features(&ids), ["graphics32"]);
    }

    #[test]
    fn data_paths() {
        for ok in [".steam", ".local/share/Steam", ".config/Plex HTPC", "a/b/c"] {
            assert!(is_data_path(ok), "{ok}");
        }
        for bad in [
            "", "/", "/etc", "~/x", "a/../b", "./a", "a/./b", "a//b", "a/", "..", "*", "a/*",
            "a\nb", "a\\b",
        ] {
            assert!(!is_data_path(bad), "{bad:?}");
        }
    }

    #[test]
    fn service_fields() {
        let i = Index::parse(
            br#"{"indexVersion":4,"entries":[
              {"id":"jellyfin-server","kind":"service","name":"Jellyfin",
               "status":"available","ports":[{"port":8096,"proto":"tcp","from":"lan"},
               {"port":7359,"proto":"udp","from":"lan"}],"setup":"jellyfin-server","stateDirs":["jellyfin"]},
              {"id":"cloudflare-tunnel","kind":"service","name":"C",
               "status":"available","ports":[],"setup":"cloudflare-tunnel",
               "stateDirs":["hinteros/services/cloudflare-tunnel"]},
              {"id":"later","kind":"service","name":"L","status":"available",
               "ports":[{"port":1,"proto":"sctp","from":"wan"}],"setup":"later"},
              {"id":"old","kind":"service","name":"O","status":"available"}]}"#,
            "/".into(),
        )
        .unwrap();
        let j = i.get("jellyfin-server").unwrap();
        assert_eq!(j.setup_kind(), Some(Setup::JellyfinServer));
        assert_eq!(j.tcp_port(), Some(8096));
        assert_eq!(j.state_dirs, ["jellyfin"]);
        let c = i.get("cloudflare-tunnel").unwrap();
        assert_eq!(c.setup_kind(), Some(Setup::CloudflareTunnel));
        assert_eq!(c.tcp_port(), None);
        // Unknown values: on/off only; unknown protocols are no TCP port.
        let l = i.get("later").unwrap();
        assert_eq!(l.setup_kind(), None);
        assert_eq!(l.ports[0].proto, Proto::Unknown);
        assert_eq!(l.ports[0].from, PortFrom::Unknown);
        assert_eq!(l.tcp_port(), None);
        // Optional: none of the three fields.
        let o = i.get("old").unwrap();
        assert!(o.ports.is_empty() && o.setup.is_none() && o.state_dirs.is_empty());
        for bad in [
            "..", "a/../b", "/var", "a//b", "a/", "a b", "$x", "a/./b", "",
        ] {
            let text = format!(
                r#"{{"indexVersion":4,"entries":[{{"id":"a","kind":"service","name":"A","status":"available","stateDirs":[{}]}}]}}"#,
                serde_json::to_string(bad).unwrap()
            );
            assert!(
                Index::parse(text.as_bytes(), "/".into()).is_err(),
                "{bad:?}"
            );
            assert!(!is_state_dir(bad), "{bad:?}");
        }
        for ok in [
            "plex",
            "hinteros/services/cloudflare-tunnel",
            "a.b_c-d",
            ".x",
        ] {
            assert!(is_state_dir(ok), "{ok}");
        }
    }

    #[test]
    fn dependencies_are_transitive_and_unique() {
        let i = Index::parse(
            br#"{"indexVersion":4,"entries":[
              {"id":"a","name":"a","status":"available","depends":["b","c"]},
              {"id":"b","name":"b","status":"available","depends":["c"]},
              {"id":"c","name":"c","status":"available","depends":["a"]},
              {"id":"d","name":"d","status":"available","depends":["zz"]}]}"#,
            "/".into(),
        )
        .unwrap();
        assert_eq!(i.with_dependencies(&["a".into()]).unwrap(), ["a", "b", "c"]);
        assert_eq!(i.with_dependencies(&["d".into()]).unwrap_err(), "zz");
        assert_eq!(i.with_dependencies(&["nope".into()]).unwrap_err(), "nope");
    }
}
